<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $lead->lead_no }}</title><style>body{font-family:system-ui;background:#f4f7fb}.shell{max-width:900px;margin:auto;padding:24px 16px}.card{background:#fff;padding:18px;border-radius:12px;margin:12px 0;border:1px solid #e2e8f0}.g{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}input,select,textarea{width:100%;padding:9px;box-sizing:border-box}textarea{min-height:90px}.full{grid-column:1/-1}.a{padding:10px 0;border-top:1px solid #edf2f7}@media(max-width:650px){.g{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><div class="shell"><a href="{{ route('tagore.admissions.index') }}">← Admissions</a><div class="card"><h1>{{ $lead->lead_no }}</h1><div class="g"><div><b>Student</b><br>{{ $lead->student_name }}</div><div><b>Parent</b><br>{{ $lead->parent_name ?: '—' }}</div><div><b>Mobile</b><br>{{ $lead->mobile ?: '—' }}</div><div><b>Class</b><br>{{ $lead->class_name ?: '—' }}</div><div><b>Status</b><br>{{ ucfirst(str_replace('_',' ',$lead->status)) }}</div><div><b>Source / Campaign</b><br>{{ $lead->source ?: '—' }}{{ $lead->campaign ? ' / '.$lead->campaign : '' }}</div><div><b>Owner</b><br>{{ optional($staff->firstWhere('id',$lead->assigned_to))->name ?: 'Unassigned' }}</div><div><b>Last contacted</b><br>{{ optional($lead->last_contacted_at)->format('d M Y H:i') ?: '—' }}</div><div><b>Follow-up</b><br>{{ optional($lead->next_follow_up_at)->format('d M Y H:i') ?: '—' }}</div></div><p>{{ $lead->notes }}</p><form method="post" action="{{ route('tagore.admissions.assign',$lead) }}" style="display:flex;gap:8px;align-items:end">@csrf @method('PATCH')<div style="flex:1"><label>Lead owner</label><select name="assigned_to" style="width:100%;padding:9px"><option value="">Unassigned</option>@foreach($staff as $person)<option value="{{ $person->id }}" @selected($lead->assigned_to===$person->id)>{{ $person->name }}</option>@endforeach</select></div><button>Assign</button></form></div><div class="card"><h2>Log follow-up</h2><form method="post" action="{{ route('tagore.admissions.activity',$lead) }}">@csrf<div class="g"><div><select name="type" required><option value="call">Call</option><option value="whatsapp">WhatsApp</option><option value="meeting">Meeting</option><option value="visit">Visit</option><option value="note">Note</option></select></div><div><select name="status"><option value="">Keep status</option>@foreach(['new','contacted','follow_up','qualified','admitted','lost'] as $s)<option value="{{ $s }}">{{ ucfirst(str_replace('_',' ',$s)) }}</option>@endforeach</select></div><div><input name="outcome" placeholder="Outcome"></div><div><input name="next_follow_up_at" type="datetime-local"></div><div><input name="lost_reason" placeholder="Lost reason (if marking lost)"></div><div class="full"><textarea name="notes" placeholder="Parent response / next action"></textarea></div></div><p><button>Save activity</button></p></form></div><div class="card"><h2>Timeline</h2>@forelse($lead->activities->sortByDesc('created_at') as $a)<div class="a"><b>{{ ucfirst($a->type) }}</b> · {{ $a->outcome ?: '—' }}<br><small>{{ $a->created_at->format('d M Y H:i') }}</small><p>{{ $a->notes }}</p></div>@empty<p>No activity yet.</p>@endforelse</div></div></body></html>